// Controle de forme + anti-doublon (fenetre 10 minutes)
const p = $input.first().json.body || $input.first().json;

if (!p || !p.client || !p.reponses || !p.reponses.contact_email) {
  throw new Error('Charge utile invalide : client, reponses ou e-mail manquant.');
}

const statique = $getWorkflowStaticData('global');
statique.recents = statique.recents || {};
const maintenant = Date.now();

// purge des empreintes de plus de 10 minutes
for (const [k, t] of Object.entries(statique.recents)) {
  if (maintenant - t > 600000) delete statique.recents[k];
}

const empreinte = p.client.cle + '|' + String(p.reponses.contact_email).toLowerCase();
const doublon = Boolean(statique.recents[empreinte]);
statique.recents[empreinte] = maintenant;

return [{ json: { ...p, doublon } }];

